import pandas as pd
import os

files = ['ERP-2025-table10.xls', 'ERP-2025-table12.xls', 'CPI.xlsx']

for f in files:
    print(f"--- Inspecting {f} ---")
    try:
        if f.endswith('.xls'):
            df = pd.read_excel(f, nrows=20, header=None) # Read raw to see layout
        else:
            df = pd.read_excel(f, nrows=20, header=None)
        print(df.head(20))
        print("\n")
    except Exception as e:
        print(f"Error reading {f}: {e}")

